MAX_BYTES=2*1024*1024
MAX_PLAYS=2000
MAX_POINTS=300
MAX_TEXT_PLAYS=80
MAX_RESPONSE_BYTES=192*1024

def number(value,low=None,high=None):
    if isinstance(value,bool):return None
    try: value=float(value)
    except (TypeError,ValueError,OverflowError):return None
    if not math.isfinite(value) or low is not None and value<low or high is not None and value>high:return None
    return int(value) if value.is_integer() else value

def text(value,limit=400):
    if value is None:return None
    value=re.sub(r'[\x00-\x1f\x7f]',' ',str(value)).strip()
    # The payload allowlist contains labels only, never raw ESPN/provider locations.
    return value[:limit] if value and not re.search(r'https?://',value,re.I) else None

def identity(value):
    value=str(value or '')
    return value if re.fullmatch(r'[A-Za-z0-9_-]{1,64}',value) else None

def plays(raw):
    source=raw.get('plays') or []
    if not isinstance(source,list) or len(source)>MAX_PLAYS:raise ValueError('Tracker play limit exceeded')
    seen=set();result=[]
    for p in source:
        if not isinstance(p,dict):continue
        ident=identity(p.get('id'))
        if not ident or ident in seen:continue
        seen.add(ident);result.append(p)
    return result

def wall(p):
    """Provider wallclock with subsecond precision; occurrence semantics uncalibrated."""
    value=p.get('wallclock') if isinstance(p,dict) else None
    if not isinstance(value,str) or not re.fullmatch(r'\d{4}-\d\d-\d\dT\d\d:\d\d(:\d\d(\.\d+)?)?Z',value):return None
    try:return datetime.fromisoformat(value.replace('Z','+00:00')).timestamp()
    except ValueError:return None

def base_play(p):
    return {'id':identity(p.get('id')), 'text':text(p.get('text')), 'type':text((p.get('type') or {}).get('text'),80),
        'team_id':identity((p.get('team') or {}).get('id')), 'period':number((p.get('period') or {}).get('number'),1,30),
        'clock':text((p.get('clock') or {}).get('displayValue'),30),'at':wall(p)}

def xy(p,key,xbounds,ybounds):
    c=p.get(key)
    if not isinstance(c,dict):return None
    x=number(c.get('x'),*xbounds);y=number(c.get('y'),*ybounds)
    return None if x is None or y is None else (x,y)

def batting_result_ids(rows):
    """ESPN labels substitutions and runner advances 'Play Result' too.
    A batter's outcome must match the explicit end-of-at-bat record.
    """
    def key(p):return (str(p.get('atBatId')),p.get('atBatPitchNumber'),wall(p))
    ends={key(p) for p in rows if (p.get('type') or {}).get('type')=='end-batterpitcher'}
    return {str(p.get('id')) for p in rows if (p.get('type') or {}).get('type')=='play-result'
            and p.get('atBatPitchNumber') is not None and key(p) in ends}


def baseball(raw,calibration,event_id,at_bat_id=None):
    rows=plays(raw)
    actual=[p for p in rows if p.get('summaryType')=='P' and number(p.get('atBatPitchNumber'),1,100) is not None]
    current_records=[p for p in rows if identity(p.get('atBatId')) and (p.get('summaryType')=='P' or (p.get('type') or {}).get('type') in ('start-batterpitcher','end-batterpitcher','play-result'))]
    selected=at_bat_id or (str(current_records[-1].get('atBatId')) if current_records else None)
    # A new batter's start record arrives before his first pitch. Keep the latest at-bat that has pitches (with its
    # own coordinates and result) until then, so the deciding pitch stays visible; flagged, never relabelled current.
    previous=False
    if not at_bat_id and selected and actual and not any(str(p.get('atBatId'))==selected for p in actual):
        selected=str(actual[-1].get('atBatId'));previous=True
    current=[p for p in actual if str(p.get('atBatId'))==selected]
    points=[];descriptions=[];seen=set()
    coords=[c for p in current if (c:=xy(p,'pitchCoordinate',(0,300),(0,300))) is not None]
    left=min([40]+[c[0]-12 for c in coords]);right=max([210]+[c[0]+12 for c in coords])
    top=min([105]+[c[1]-12 for c in coords]);bottom=max([245]+[c[1]+12 for c in coords])
    width=right-left;height=bottom-top
    for p in current:
        n=number(p.get('atBatPitchNumber'),1,100)
        if n in seen:continue
        seen.add(n);row=base_play(p);counts=p.get('resultCount') or {}
        row.update(number=n,pitch_type=text((p.get('pitchType') or {}).get('text'),80),mph=number(p.get('pitchVelocity'),1,120),
            balls=number(counts.get('balls'),0,4),strikes=number(counts.get('strikes'),0,3),result=text((p.get('type') or {}).get('type'),60))
        descriptions.append(row);coordinate=xy(p,'pitchCoordinate',(0,300),(0,300))
        if coordinate and calibration['verified']:points.append({**row,'x':(coordinate[0]-left)/width,'y':(coordinate[1]-top)/height})
    last=descriptions[-1] if descriptions else {}
    result_ids=batting_result_ids(rows)
    result_rows=[p for p in rows if str(p.get('atBatId'))==selected and str(p.get('id')) in result_ids]
    summary={'at_bat_id':identity(selected),'pitch_count':len(descriptions),'balls':last.get('balls'),'strikes':last.get('strikes'),
        'outcome':text(result_rows[-1].get('text')) if result_rows else None,'completed':bool(result_rows),
        'scope':'previous_at_bat' if previous else 'current_or_latest_at_bat'}
    field={'width':1,'height':1,'physical_width':width,'physical_height':height,'units':'ESPN pitch units',
        'viewport':{'x_min':left,'x_max':right,'y_min':top,'y_max':bottom},
        'zone':{'x':(88-left)/width,'y':(149-top)/height,'width':56/width,'height':44/height,'approximate':True}}
    physical={str(p['id']):g for p in current if (g:=physical_geometry(p.get('_mlb_geometry'))) is not None}
    if physical:
        g=list(physical.values())[-1];field=physical_field(g)
        points=[{**row,'x':physical_point(physical[row['id']])[0],'y':physical_point(physical[row['id']])[1]} for row in descriptions if row['id'] in physical]
        summary['location_pending']=len(descriptions)-len(points)
    return field,points,descriptions,summary,bool(calibration['verified'])

def basketball(raw,calibration,event_id):
    points=[];descriptions=[];counts={}
    for p in plays(raw):
        attempted=number(p.get('pointsAttempted'),2,3)
        if p.get('shootingPlay') is not True or attempted not in (2,3):continue
        row=base_play(p);made=p.get('scoringPlay') is True
        row.update(made=made,value=number(p.get('scoreValue'),0,3),points_attempted=attempted)
        descriptions.append(row)
        if row['team_id']:
            count=counts.setdefault(row['team_id'],{'team_id':row['team_id'],'fg_made':0,'fg_attempts':0,'three_made':0,'three_attempts':0})
            count['fg_attempts']+=1;count['fg_made']+=int(made)
            if attempted==3:count['three_attempts']+=1;count['three_made']+=int(made)
        coordinate=xy(p,'coordinate',(0,50),(-5.25,41.75))
        if coordinate and calibration['verified']:points.append({**row,'x':coordinate[0]/50,'y':(coordinate[1]+5.25)/47})
    field={'width':1,'height':1,'physical_width':50,'physical_height':47,'units':'feet','hoop':{'x':.5,'y':5.25/47}}
    return field,points,descriptions,{'teams':list(counts.values()),'scope':'reported_field_goal_plays'},bool(calibration['verified'])

def hockey_directions(raw, rows, calibration):
    """Conservative per-period end inference. Never assign a team to unlabelled shots."""
    competitors=((raw.get('header') or {}).get('competitions') or [{}])[0].get('competitors') or []
    sides={c.get('homeAway'):identity((c.get('team') or {}).get('id') or c.get('id')) for c in competitors}
    evidence={};directions={};diagnostics=[]
    for p in rows:
        if (p.get('type') or {}).get('text') not in ('Shot','Goal'):continue
        period=number((p.get('period') or {}).get('number'),1,3)
        tid=identity((p.get('team') or {}).get('id'));coord=xy(p,'coordinate',(-100,100),(-42.5,42.5))
        if period is None or tid not in sides.values() or not coord or abs(coord[0])<=20:continue
        bucket=evidence.setdefault(period,{}).setdefault(tid,[0,0]);bucket[int(coord[0]>0)]+=1
    # Optional explicit source mapping is internal validated metadata, never a client parameter.
    explicit=calibration.get('explicit_period_home_positive') or {}
    for period in (1,2,3):
        buckets=evidence.get(period,{});home=buckets.get(sides.get('home'),[0,0]);away=buckets.get(sides.get('away'),[0,0])
        detail={'period':period,'home_negative':home[0],'home_positive':home[1], 'away_negative':away[0],'away_positive':away[1]}
        supplied=explicit.get(period)
        if isinstance(supplied,bool):
            directions[period]=supplied;detail.update(status='explicit',reason=None);diagnostics.append(detail);continue
        candidates=[]
        for side,counts in [('home',home),('away',away)]:
            total=sum(counts)
            if total>=5 and max(counts)/total>=.8:
                positive=counts[1]>counts[0];candidates.append(positive if side=='home' else not positive)
        if not candidates:detail.update(status='omitted',reason='Insufficient or ambiguous shots: need at least five, 80% beyond center toward one end.')
        else:
            direction=candidates[0]
            consistent=all(c==direction for c in candidates)
            for counts,expected in [(home,direction),(away,not direction)]:
                if sum(counts) and counts[int(expected)]/sum(counts)<.8:consistent=False
            if consistent:directions[period]=direction;detail.update(status='inferred',reason=None)
            else:detail.update(status='omitted',reason='Opposing team shot locations conflict with inferred end.')
        diagnostics.append(detail)
    # Regulation teams switch ends. Contradictory independently inferred periods fail closed.
    initial={value if period%2 else not value for period,value in directions.items()}
    if len(initial)>1:
        directions.clear()
        for detail in diagnostics:detail.update(status='omitted',reason='Reported period ends conflict with regulation end switching.')
    return directions,diagnostics


def hockey(raw,calibration,event_id):
    points=[];descriptions=[];counts={};rows=plays(raw)
    directions,diagnostics=hockey_directions(raw,rows,calibration)
    raw_axes=calibration.get('raw_axes_verified') is True
    geometry=raw_axes and bool(directions)
    calibration['periods']=diagnostics
    calibration['direction_derived']=any(d.get('status')=='inferred' for d in diagnostics)
    calibration['geometry_available']=geometry
    calibration['orientation_method']='inferred_from_shot_locations' if calibration['direction_derived'] else 'explicit_source_ends' if directions else 'unavailable'
    for p in rows:
        kind=(p.get('type') or {}).get('text')
        if kind not in ('Shot','Goal'):continue
        row=base_play(p);row['made']=kind=='Goal';descriptions.append(row)
        if row['team_id']:
            count=counts.setdefault(row['team_id'],{'team_id':row['team_id'],'shots_on_goal':0,'goals':0})
            count['shots_on_goal']+=1;count['goals']+=int(kind=='Goal')
        coordinate=xy(p,'coordinate',(-100,100),(-42.5,42.5));period=row['period']
        if coordinate and geometry and period in directions:
            x,y=coordinate
            if not directions[period]:x,y=-x,-y
            points.append({**row,'x':(x+100)/200,'y':(42.5-y)/85})
    field={'width':1,'height':1,'physical_width':200,'physical_height':85,'units':'feet',
        'goals':[{'x':.055,'y':.5},{'x':.945,'y':.5}], 'orientation':'home attacks right; away attacks left; regulation only'}
    return field,points,descriptions,{'teams':list(counts.values()),'scope':'reported_shots_on_goal'},False

def football(raw,calibration,event_id,drive_id=None):
    drives=raw.get('drives') or {};previous=drives.get('previous') or []
    if not isinstance(previous,list) or len(previous)>100:raise ValueError('Tracker drive limit exceeded')
    all_drives=previous+([drives['current']] if isinstance(drives.get('current'),dict) else [])
    drive=next((d for d in all_drives if str(d.get('id'))==str(drive_id)),{}) if drive_id else (all_drives[-1] if all_drives else {})
    rows=drive.get('plays') or []
    if not isinstance(rows,list) or len(rows)>MAX_PLAYS:raise ValueError('Tracker play limit exceeded')
    team=identity((drive.get('team') or {}).get('id'));descriptions=[];points=[];seen=set()
    for p in rows:
        row=base_play(p)
        if not row['id'] or row['id'] in seen:continue
        seen.add(row['id']);start=p.get('start') or {};end=p.get('end') or {}
        row.update(team_id=team,down_distance=text(start.get('downDistanceText'),100),yards=number(p.get('statYardage'),-100,100),
            down=number(start.get('down'),1,4),distance=number(start.get('distance'),0,100))
        # yardsToEndzone is explicitly possession-relative. Never infer direction from the event.
        a=number(start.get('yardsToEndzone'),0,100);b=number(end.get('yardsToEndzone'),0,100)
        same_team=team and identity((start.get('team') or {}).get('id'))==team and identity((end.get('team') or {}).get('id'))==team
        scrimmage=not re.search(r'timeout|end period|end of (half|game|quarter)|kickoff|coin toss|two-minute',row.get('type') or '',re.I)
        if calibration['verified'] and same_team and scrimmage and a is not None and b is not None:
            # Sept 26: yards = the ball's actual movement (a penalty-wiped 22-yd pass reported statYardage +10
            # while the ball went back 10); statYardage stays the fallback when spots are missing.
            row.update(start_x=(100-a)/100,end_x=(100-b)/100,yards=a-b)
        descriptions.append(row)
    summary={'drive_id':identity(drive.get('id')),'team_id':team,'result':text(drive.get('displayResult') or drive.get('result'),80),
        'description':text(drive.get('description'),160),'scope':'current_or_latest_drive'}
    field={'width':1,'height':1,'physical_width':100,'physical_height':53.333333,'units':'yards','orientation':'possession team attacks right'}
    # Sept 26: the current ball spot (end of the latest same-possession play) for a line-of-scrimmage marker.
    current=drives.get('current') if isinstance(drives.get('current'),dict) else {}
    ends=[r['end_x'] for r in descriptions if 'end_x' in r]
    if ends and current and str(current.get('id'))==str(drive.get('id')) and not drive_id:field['ball_x']=ends[-1]
    return field,points,descriptions,summary,bool(calibration['verified'])

def recent_results(raw,limit=6):
    """Completed MLB plate appearances (provider play-result records only), newest last, with the reported score."""
    rows=[p for p in plays(raw) if (p.get('type') or {}).get('type')=='play-result']
    out=[]
    for p in rows[-limit:]:
        per=p.get('period') or {}
        out.append({'id':identity(p.get('id')),'text':text(p.get('text'),200),'inning':text(per.get('displayValue'),20),'at':wall(p),
            'team_id':identity((p.get('team') or {}).get('id')),'away':number(p.get('awayScore'),0,99),'home':number(p.get('homeScore'),0,99)})
    return out

def drive_flow(raw,calibration,limit=40):
    """Every drive's reported result and span. Span only from possession-relative yardsToEndzone of its own plays."""
    drives=raw.get('drives') or {};previous=drives.get('previous') or []
    if not isinstance(previous,list):return []
    all_drives=(previous+([drives['current']] if isinstance(drives.get('current'),dict) else []))[-limit:]
    out={}
    for d in all_drives:
        team=identity((d.get('team') or {}).get('id'));rows=[p for p in (d.get('plays') or []) if isinstance(p,dict)]
        result=text(d.get('displayResult') or d.get('result'),60)
        if result and re.fullmatch(r'end of (game|half|regulation)',result,re.I):result='Clock ran out'
        after=next((p for p in reversed(rows) if number(p.get('awayScore'),0,999) is not None and number(p.get('homeScore'),0,999) is not None),None)
        row={'id':identity(d.get('id')),'team_id':team,'result':result,
            'away':number(after.get('awayScore'),0,999) if after else None,'home':number(after.get('homeScore'),0,999) if after else None,
            'scoring':bool(d.get('isScore')) or any(p.get('scoringPlay') is True for p in rows),
            'yards':number(d.get('yards'),-100,200),'plays':number(d.get('offensivePlays'),0,60),'description':text(d.get('description'),120)}
        if calibration.get('verified') and rows and team:
            # Sept 26: yardsToEndzone is relative to whoever has the ball at that moment; only use values
            # measured for the drive team (a punt/turnover's end belongs to the other team).
            mine=lambda side,p:identity(((p.get(side) or {}).get('team') or {}).get('id'))==team
            a=next((number((p.get('start') or {}).get('yardsToEndzone'),0,100) for p in rows if mine('start',p)),None)
            b=None
            for p in rows:
                if mine('end',p):b=number((p.get('end') or {}).get('yardsToEndzone'),0,100)
                elif mine('start',p):b=number((p.get('start') or {}).get('yardsToEndzone'),0,100)
            if a is not None and b is not None:row.update(start_x=(100-a)/100,end_x=(100-b)/100)
        # Reuse the existing possession-safe normalizer, with bounded sanitized details.
        selected={'drives':{'previous':[d]}}
        row['play_details']=football(selected,calibration,'drive-detail',row['id'])[2][-40:]
        out[row['id'] or '#'+str(len(out))]=row          # the in-progress drive appears in 'previous' and 'current'
    return list(out.values())

MAX_TIMELINE=160

def soccer_rows(raw, now=None):
    """Sequence preserves order independently of ingestion wallclock.

    Only actual nested ESPN IDs and sequence qualify. Multiple commentary lines
    can share one play, so presentation row IDs combine that ID and sequence,
    retaining the real play_id separately. KeyEvents enriches by exact play ID;
    scores after a play and pitch geometry are never guessed from prose.
    """
    source=raw.get('commentary') or [];keys=raw.get('keyEvents') or []
    if not isinstance(source,list) or len(source)>MAX_PLAYS or not isinstance(keys,list) or len(keys)>MAX_PLAYS:
        raise ValueError('Soccer commentary limit exceeded')
    enrich={identity(p.get('id')):p for p in keys if isinstance(p,dict) and identity(p.get('id'))}
    now=time.time() if now is None else now;rows={};ambiguous=set()
    for c in source:
        if not isinstance(c,dict) or not isinstance(c.get('play'),dict):continue
        p=c['play'];ident=identity(p.get('id'));sequence=number(c.get('sequence'),0,1_000_000)
        if not ident or not isinstance(sequence,int):continue
        row_id=ident+'_'+str(sequence)
        if row_id in ambiguous:continue
        at=wall(p)
        if at is not None and at>now:continue
        row=base_play(p);key=enrich.get(ident,{})
        row.update(id=row_id,play_id=ident,sequence=sequence,text=text(c.get('text') or p.get('text')),
            team_id=identity((key.get('team') or {}).get('id')) or row['team_id'],
            scoring=key.get('scoringPlay') is True,away=None,home=None,
            clock_seconds=number((p.get('clock') or {}).get('value'),0,18_000))
        if not row['text']:continue
        if row_id in rows and rows[row_id]!=row:
            rows.pop(row_id);ambiguous.add(row_id);continue
        rows[row_id]=row
    # An ID or sequence collision cannot safely establish a commentary cutoff.
    counts={}
    for row in rows.values():counts[row['sequence']]=counts.get(row['sequence'],0)+1
    return sorted((p for p in rows.values() if counts[p['sequence']]==1),key=lambda p:p['sequence'])

def soccer(raw,calibration,event_id,now=None):
    return {},[],soccer_rows(raw,now),{'scope':'reported_commentary','picture_timing_verified':False},False

def football_goal_to_go(end):
    """Only the explicit, internally consistent reported end state is Goal.

    Positive numeric distance remains available for geometry. A matching spot,
    yardsToEndzone, start state, or play description cannot establish Goal.
    """
    if not isinstance(end,dict):return False
    down=number(end.get('down'),1,4)
    if type(down) is not int:return False
    declared=end.get('goalToGo')
    if declared is not None and type(declared) is not bool or declared is False:return False
    labels=[]
    for key in ('shortDownDistanceText','downDistanceText'):
        value=end.get(key)
        if value is None:continue
        if not isinstance(value,str) or len(value)>100 or re.search(r'[\x00-\x1f\x7f]|https?://',value,re.I):return False
        value=value.strip()
        if value:labels.append(value)
    if not labels:return declared is True
    goals=[re.fullmatch(r'(1st|2nd|3rd|4th)\s*&\s*Goal(?:\s+at\s+[A-Z]{2,4}\s+[0-9]{1,2})?',label,re.I) for label in labels]
    return all(goal and int(goal[1][0])==down for goal in goals)

def timeline(raw,kind,limit=MAX_TIMELINE,now=None):
    """Sept 29 (same-game sync): every reported play with ESPN's real-world time and the score after it, newest last.
    Clients hold each entry until their own picture reaches it (now - delay), so the watched game can have a tracker
    without spoilers. Pitch locations stay on their own timestamped rows."""
    if kind=='soccer':
        return [p for p in soccer_rows(raw,now) if p['at'] is not None][-limit:]
    if kind=='football':
        drives=raw.get('drives') or {};previous=drives.get('previous') or []
        source=[]
        for d in (previous if isinstance(previous,list) else [])+([drives['current']] if isinstance(drives.get('current'),dict) else []):
            if isinstance(d,dict):
                team=identity((d.get('team') or {}).get('id'))
                source+=[(p,team) for p in (d.get('plays') or []) if isinstance(p,dict)]
    else:
        source=[(p,None) for p in plays(raw)]
    result_ids=batting_result_ids([p for p,_ in source]) if kind=='baseball' else set()
    out={}
    for p,team in source:
        at=wall(p);ident=identity(p.get('id'))
        if at is None or not ident:continue
        per=p.get('period') or {}
        row={'id':ident,'at':at,'text':text(p.get('text'),400 if kind=='football' else 160),'type':text((p.get('type') or {}).get('text'),60),
            'period':number(per.get('number'),1,30),'clock':text((p.get('clock') or {}).get('displayValue'),20),
            'away':number(p.get('awayScore'),0,999),'home':number(p.get('homeScore'),0,999),'scoring':p.get('scoringPlay') is True,
            'team_id':identity((p.get('team') or {}).get('id')) or team}
        if kind=='baseball':
            counts=p.get('resultCount') or {}
            row.update(pitch_number=number(p.get('atBatPitchNumber'),1,100),
                pitch_type=text((p.get('pitchType') or {}).get('text'),60),mph=number(p.get('pitchVelocity'),1,120),
                half=text(per.get('type'),10),inning=text(per.get('displayValue'),20),outs=number(p.get('outs'),0,3),
                pitch=p.get('summaryType')=='P',result=str(p.get('id')) in result_ids,at_bat=identity(p.get('atBatId')),
                balls=number(counts.get('balls'),0,4),strikes=number(counts.get('strikes'),0,3),
                bases=[n for n,k in ((1,'onFirst'),(2,'onSecond'),(3,'onThird')) if p.get(k)])
            coordinate=xy(p,'pitchCoordinate',(0,300),(0,300))
            if row['pitch'] and coordinate and CALIBRATION['baseball']['verified']:
                row.update(pitch_x=coordinate[0]/300,pitch_y=coordinate[1]/300,
                    pitch_number=number(p.get('atBatPitchNumber'),1,100),
                    pitch_type=text((p.get('pitchType') or {}).get('text'),60),
                    mph=number(p.get('pitchVelocity'),1,120))
            physical=physical_geometry(p.get('_mlb_geometry'))
            if row['pitch'] and physical:row['physical']=physical
        elif kind=='football':
            end=p.get('end') or {}
            row.update(down=number(end.get('down'),1,4),distance=number(end.get('distance'),0,100),spot=text(end.get('possessionText'),30),
                yards=number(p.get('statYardage'),-100,110),possession=identity((end.get('team') or {}).get('id')))
            if football_goal_to_go(end):row['goal_to_go']=True
        out[ident]=row
    rows=sorted(out.values(),key=lambda r:r['at'])
    return rows[-limit:]

NORMALIZERS={'baseball':baseball,'basketball':basketball,'hockey':hockey,'football':football,'soccer':soccer}

def provider_lifecycle(comp,typ,event,status,start):
    """Export only literal provider lifecycle types; legacy fallbacks are not proof."""
    labels={'STATUS_SCHEDULED':('pre',False),'STATUS_SUSPENDED':('in',False),'STATUS_DELAYED':('in',False),'STATUS_IN_PROGRESS':('in',False)}
    if not isinstance(typ,dict) or typ.get('name') not in labels:return None
    state,completed=labels[typ['name']]
    if typ.get('state')!=state or type(typ.get('completed')) is not bool or typ['completed']!=completed:return None
    ident=typ.get('id')
    if not isinstance(ident,str) or not re.fullmatch(r'[0-9]{1,3}',ident) or typ['name']=='STATUS_SCHEDULED' and ident!='1':return None
    if str(comp.get('id'))!=str(event) or not isinstance(status,str) or not 0<len(status)<=120 or not isinstance(start,str) or not 0<len(start)<=40:return None
    return {'source':'ESPN','id':ident,'name':typ['name'],'state':state,'completed':completed,'event_id':str(event),'status':status,'start':start}

def normalize(raw,league,event_id,fetched_at=None,calibrations=None):
    if league not in LEAGUES:raise ValueError('Unsupported tracker league')
    header=raw.get('header') or {}
    if str(header.get('id'))!=str(event_id):raise ValueError('Tracker identity mismatch')
    competitions=header.get('competitions') or []
    comp=next((c for c in competitions if str(c.get('id'))==str(event_id)),None)
    if not comp:raise ValueError('Tracker competition missing')
    status=comp.get('status') or {};typ=status.get('type') or {}
    state='live' if typ.get('state')=='in' else 'final' if typ.get('completed') is True else 'scheduled'
    if typ.get('name') in ('STATUS_POSTPONED','STATUS_CANCELED','STATUS_CANCELLED'):state='unavailable'
    if league in ('NFL','College football') and (state=='scheduled' or typ.get('name')=='STATUS_SCHEDULED') and not (typ.get('id')=='1' and typ.get('name')=='STATUS_SCHEDULED' and typ.get('state')=='pre' and type(typ.get('completed')) is bool and typ['completed'] is False):state='unavailable'
    kind=LEAGUES[league][1];cal=copy.deepcopy((calibrations or CALIBRATION)[kind])
    report_time=number(fetched_at,0) if fetched_at is not None else time.time()
    if report_time is None:raise ValueError('Invalid tracker observation time')
    field,points,descriptions,summary,verified=(soccer(raw,cal,str(event_id),report_time) if kind=='soccer' else NORMALIZERS[kind](raw,cal,str(event_id)))
    if kind=='baseball' and field.get('source')=='mlb':
        cal.update(display='MLB tracked locations Â· batter-specific zone',note='MLB physical pitch coordinates and reported batter zone; nominal ball size, umpire calls preserved.',source='https://baseballsavant.mlb.com/abs')
    if state not in ('live','final'):points=[];descriptions=[];summary={}
    # Drop unknown/missing team IDs rather than assigning plays to an inferred team.
    teams=[]
    for c in comp.get('competitors') or []:
        t=c.get('team') or {};ident=identity(t.get('id') or c.get('id'))
        if ident:teams.append({'logo':team_logo(t),'id':ident,'name':text(t.get('displayName'),100),'abbreviation':text(t.get('abbreviation'),12),
            'side':c.get('homeAway') if c.get('homeAway') in ('home','away') else None,'score':text(c.get('score'),20) if state in ('live','final') else None,
            'color':'#'+str(t.get('color')).lower() if re.fullmatch(r'[0-9a-fA-F]{6}',str(t.get('color') or '')) else None,
            'alt_color':'#'+str(t.get('alternateColor')).lower() if re.fullmatch(r'[0-9a-fA-F]{6}',str(t.get('alternateColor') or '')) else None})
    known={t['id'] for t in teams}
    points=[p for p in points if p.get('team_id') in known]
    if kind=='football':
        for p in descriptions:
            if p.get('team_id') not in known:p.pop('start_x',None);p.pop('end_x',None)
    geometry=bool(cal.get('geometry_available',verified))
    available=geometry and (bool(points) or kind=='football' and any('start_x' in p for p in descriptions))
    # Sept 26: right after a kickoff/turnover the new drive has no snap yet; that is not missing ESPN data
    # when earlier drives carried field positions (observed on a fourth-quarter drive).
    earlier=kind=='football' and any(number(((p.get('start') or {}).get('yardsToEndzone')),0,100) is not None
        for d in ((raw.get('drives') or {}).get('previous') or []) if isinstance(d,dict) for p in (d.get('plays') or []) if isinstance(p,dict))
    reason=('Commentary from ESPN Â· picture timing unverified' if kind=='soccer' else None if available else 'Play locations are not available for this game.' if not geometry else
            'Pitch and play locations appear once the game is under way.' if state=='scheduled' else
            'New drive â€” the chart starts with the first snap.' if state=='live' and earlier else
            'ESPN is not sending play locations for this game right now.')
    truncated=len(points)>MAX_POINTS or len(descriptions)>MAX_TEXT_PLAYS
    result={'schema_version':1,'event_id':str(event_id),'league':league,'kind':kind,'state':state,'status':text(typ.get('shortDetail') or typ.get('detail') or typ.get('description'),120),
        'start':text(comp.get('date'),40),'period':number(status.get('period'),0,30),'clock':text(status.get('displayClock'),30),'teams':teams,
        'fetched_at':fetched_at or time.time(),'source_updated_at':text((raw.get('meta') or {}).get('lastUpdatedAt'),40),'stale':False,
        'tracking_available':bool(available),'orientation_verified':bool(verified),'geometry_available':geometry,'raw_axes_verified':bool(cal.get('raw_axes_verified',verified)),
        'direction_derived':bool(cal.get('direction_derived',False)),'orientation_method':cal.get('orientation_method','official_gamecast' if verified else 'unavailable'),'unavailable_reason':reason,
        'calibration':{'status':'verified' if verified else 'derived' if geometry else 'unverified','periods':cal.get('periods',[]),'note':cal.get('display') or CALIBRATION.get(kind,{}).get('display') or cal.get('note'),'method':cal.get('note'),'source':cal.get('source'),'coordinate_system':None if kind=='soccer' else 'normalized-top-left'},
        'field':field,'points':points[-MAX_POINTS:],'plays':descriptions[-MAX_TEXT_PLAYS:],'summary':summary,'truncated':truncated,'poll_interval_seconds':10}
    lifecycle=provider_lifecycle(comp,typ,event_id,result['status'],result['start']) if league in ('NFL','College football') else None
    if lifecycle is not None:result['provider_lifecycle']=lifecycle
    if kind=='soccer':result['commentary_available']=bool(descriptions)
    # Sept 26: the current down & distance from the latest play's reported end state (ESPN's scoreboard
    # situation often omits fields between plays; the play-by-play keeps them).
    if kind=='football' and state=='live':
        current=((raw.get('drives') or {}).get('current') or {})
        current_plays=[p for p in (current.get('plays') or []) if isinstance(p,dict)]
        for p in reversed(current_plays):
            end=p.get('end') or {};down=number(end.get('down'),1,4);distance=number(end.get('distance'),0,100)
            spot=text(end.get('possessionText'),30)
            if down and distance is not None and spot:
                result['situation']={'down':down,'distance':distance,'spot':spot,'text':text(end.get('downDistanceText'),60),
                                     'team_id':identity(((end.get('team') or {}).get('id')))}
                if p is current_plays[-1] and football_goal_to_go(end):result['situation']['goal_to_go']=True
                break
    # Sept 27: live baseball situation (count, outs, runners) for the Sports board's compact card graphic.
    if kind=='baseball' and state=='live':
        sit=raw.get('situation') if isinstance(raw.get('situation'),dict) else {}
        if sit:
            def who(x):
                a=(x or {}).get('athlete') if isinstance(x,dict) else None
                return text((a or {}).get('shortName') or (a or {}).get('displayName'),40) if isinstance(a,dict) else None
            def count(key,high):
                v=number(sit.get(key),0,high)
                return int(v) if v is not None else None
            result['situation']={'balls':count('balls',4),'strikes':count('strikes',3),'outs':count('outs',3),
                                 'on_first':bool(sit.get('onFirst')),'on_second':bool(sit.get('onSecond')),'on_third':bool(sit.get('onThird')),
                                 'batter':who(sit.get('batter')),'pitcher':who(sit.get('pitcher'))}
    if state in ('live','final'):
        result['timeline']=timeline(raw,kind,now=report_time)
        if kind=='baseball':result['recent']=recent_results(raw)
        if kind=='football':result['drives']=[d for d in drive_flow(raw,cal) if d.get('team_id') in known]
    while result.get('timeline') and len(json.dumps(result).encode())>MAX_RESPONSE_BYTES and len(result['timeline'])>40:
        result['timeline']=result['timeline'][-(len(result['timeline'])*3//4):]
    if kind=='football':
        for drive in result.get('drives',[]):
            if len(json.dumps(result).encode())<=MAX_RESPONSE_BYTES:break
            drive.pop('play_details',None)
    if len(json.dumps(result).encode())>MAX_RESPONSE_BYTES:raise ValueError('Normalized tracker limit exceeded')
    return result

# Physical MLB geometry is additive. It never changes ESPN event times or calls.
def mlb_name(value):
    import unicodedata
    return re.sub(r'[^a-z0-9]', '', unicodedata.normalize('NFKD', str(value or '')).encode('ascii','ignore').decode().lower())

def mlb_signature(raw):
    comp=next((c for c in (raw.get('header') or {}).get('competitions',[]) if str(c.get('id'))==str((raw.get('header') or {}).get('id'))),{})
    teams={c.get('homeAway'):mlb_name((c.get('team') or {}).get('displayName')) for c in comp.get('competitors',[])}
    try:start=datetime.fromisoformat(comp['date'].replace('Z','+00:00')).timestamp()
    except (KeyError,ValueError,TypeError):return None
    return (teams['home'],teams['away'],start) if teams.get('home') and teams.get('away') else None

def mlb_schedule_game(raw,schedule):
    signature=mlb_signature(raw)
    if not signature:return None
    matches=[]
    for day in schedule.get('dates',[])[:5]:
        for game in day.get('games',[])[:60]:
            teams=game.get('teams') or {}
            names=tuple(mlb_name(((teams.get(side) or {}).get('team') or {}).get('name')) for side in ('home','away'))
            try:stamp=datetime.fromisoformat(game['gameDate'].replace('Z','+00:00')).timestamp()
            except (KeyError,ValueError,TypeError):continue
            if names==signature[:2] and abs(stamp-signature[2])<=900 and number(game.get('gamePk'),1):matches.append(int(game['gamePk']))
    return matches[0] if len(matches)==1 else None

def mlb_pitch_geometry(raw,feed,game_pk):
    """Fail closed on game/matchup/pitch ambiguity; never join by clock proximity."""
    signature=mlb_signature(raw);gd=feed.get('gameData') or {};teams=gd.get('teams') or {}
    if not signature or feed.get('gamePk')!=game_pk:return {}
    if tuple(mlb_name((teams.get(side) or {}).get('name')) for side in ('home','away'))!=signature[:2]:return {}
    try:stamp=datetime.fromisoformat(gd['datetime']['dateTime'].replace('Z','+00:00')).timestamp()
    except (KeyError,ValueError,TypeError):return {}
    if abs(stamp-signature[2])>900:return {}
    candidates={}
    for ab in ((feed.get('liveData') or {}).get('plays') or {}).get('allPlays',[])[:300]:
        about=ab.get('about') or {};match=ab.get('matchup') or {}
        key=(about.get('inning'),str(about.get('halfInning')).lower(),mlb_name((match.get('pitcher') or {}).get('fullName')),mlb_name((match.get('batter') or {}).get('fullName')))
        candidates.setdefault(key,[]).append(ab)
    starts={};duplicate=set()
    for p in plays(raw):
        if (p.get('type') or {}).get('type')!='start-batterpitcher':continue
        match=re.fullmatch(r'(.+?) pitches to (.+)',str(p.get('text') or ''))
        if not match:continue
        per=p.get('period') or {};ab=str(p.get('atBatId'))
        key=(per.get('number'),str(per.get('type')).lower(),mlb_name(match[1]),mlb_name(match[2]))
        if ab in starts and starts[ab]!=key:duplicate.add(ab)
        starts[ab]=key
    multiplicity={}
    for p in plays(raw):
        if p.get('summaryType')=='P':
            identity_key=(str(p.get('atBatId')),p.get('atBatPitchNumber'));multiplicity[identity_key]=multiplicity.get(identity_key,0)+1
    output={};used=set()
    for p in plays(raw):
        ab=str(p.get('atBatId'));key=starts.get(ab)
        matches=candidates.get(key,[])
        if p.get('summaryType')!='P' or ab in duplicate or len(matches)!=1 or multiplicity.get((ab,p.get('atBatPitchNumber')))!=1:continue
        events=[e for e in matches[0].get('playEvents',[]) if e.get('isPitch') and e.get('pitchNumber')==p.get('atBatPitchNumber')]
        if len(events)!=1:continue
        e=events[0];data=e.get('pitchData') or {};coord=data.get('coordinates') or {};schematic=p.get('pitchCoordinate') or {}
        # Count and provider schematic agreement catch pitch-number shifts/corrections.
        counts=p.get('resultCount') or {};count=e.get('count') or {}
        if any(number(counts.get(k)) is None or number(counts.get(k))!=number(count.get(k)) for k in ('balls','strikes')):continue
        if any(number(schematic.get(k)) is None or number(coord.get(k)) is None or abs(float(schematic[k])-float(coord[k]))>2 for k in ('x','y')):continue
        px=number(coord.get('pX'),-5,5);pz=number(coord.get('pZ'),-2,8)
        top=number(data.get('strikeZoneTop'),2,5);bottom=number(data.get('strikeZoneBottom'),.5,3)
        width=number(data.get('strikeZoneWidth'),16.99,17.01);play_id=identity(e.get('playId'))
        if None in (px,pz,top,bottom,width) or top<=bottom or not play_id or play_id in used:continue
        used.add(play_id)
        output[str(p['id'])]={'source':'mlb','game_pk':game_pk,'play_id':play_id,'x_ft':px,'z_ft':pz,
            'top_ft':top,'bottom_ft':bottom,'width_in':width,'ball_radius_in':1.45,
            'ball_size':'nominal','perspective':'pitcher','units':'feet'}
    return output

def physical_geometry(value):
    if not isinstance(value,dict) or value.get('source')!='mlb' or value.get('perspective')!='pitcher':return None
    keys={'x_ft':(-5,5),'z_ft':(-2,8),'top_ft':(2,5),'bottom_ft':(.5,3),'width_in':(16.99,17.01),'ball_radius_in':(1.4,1.5)}
    if any(number(value.get(k),*bounds) is None for k,bounds in keys.items()) or value['top_ft']<=value['bottom_ft']:return None
    if not identity(value.get('play_id')) or number(value.get('game_pk'),1) is None:return None
    return value

def physical_point(g):
    return ((5-g['x_ft'])/10,(8-g['z_ft'])/10)

def physical_field(g):
    return {'width':1,'height':1,'physical_width':10,'physical_height':10,'units':'feet','source':'mlb',
        'ball_radius':g['ball_radius_in']/120,'ball_size':'nominal',
        'zone':{'x':(5-g['width_in']/24)/10,'y':(8-g['top_ft'])/10,'width':g['width_in']/120,
                'height':(g['top_ft']-g['bottom_ft'])/10,'approximate':False}}

class MLBGeometryCache:
    """Two bounded asynchronous public-data lanes; no delay on the tracker request."""
    def __init__(self,fetcher=None,clock=time.monotonic):
        self.fetcher=fetcher or self._fetch;self.clock=clock;self.lock=threading.Lock();self.entries={};self.slots=threading.BoundedSemaphore(2)
    @staticmethod
    def _fetch(url):
        request=urllib.request.Request(url,headers={'Accept':'application/json','User-Agent':'Orbital pitch geometry'})
        with urllib.request.urlopen(request,timeout=4) as response:data=response.read(6*1024*1024+1)
        if len(data)>6*1024*1024:raise ValueError('MLB geometry size limit')
        result=json.loads(data)
        if not isinstance(result,dict):raise ValueError('MLB geometry object required')
        return result
    def enrich(self,raw):
        signature=mlb_signature(raw);eid=identity((raw.get('header') or {}).get('id'))
        if not signature or not eid:return raw
        key=(eid,signature);now=self.clock()
        with self.lock:
            for old,e in list(self.entries.items()):
                if old!=key and not e['pending'] and now-e['touched']>600:del self.entries[old]
            if key not in self.entries:
                if len(self.entries)>=8:return raw
                self.entries[key]={'pending':False,'retry':0,'touched':now,'feed':None,'game':None}
            entry=self.entries[key];entry['touched']=now;feed=entry['feed'];game=entry['game']
            if not entry['pending'] and now>=entry['retry'] and self.slots.acquire(blocking=False):
                entry['pending']=True
                threading.Thread(target=self._load,args=(entry,copy.deepcopy(raw)),daemon=True,name='mlb-geometry').start()
        if feed:
            geometry=mlb_pitch_geometry(raw,feed,game)
            for p in raw.get('plays',[]):
                if str(p.get('id')) in geometry:p['_mlb_geometry']=geometry[str(p['id'])]
        return raw
    def _load(self,entry,raw):
        try:
            game=entry['game']
            if game is None:
                from datetime import timedelta,timezone
                day=datetime.fromtimestamp(mlb_signature(raw)[2],timezone.utc).date()
                schedule=self.fetcher('https://statsapi.mlb.com/api/v1/schedule?sportId=1&startDate='+str(day-timedelta(days=1))+'&endDate='+str(day+timedelta(days=1)))
                game=mlb_schedule_game(raw,schedule)
            if game is None:raise ValueError('No unique MLB game')
            feed=self.fetcher('https://statsapi.mlb.com/api/v1.1/game/'+str(game)+'/feed/live')
            if feed.get('gamePk')!=game:raise ValueError('MLB game identity mismatch')
            final=((feed.get('gameData') or {}).get('status') or {}).get('abstractGameState')=='Final'
            with self.lock:entry.update(feed=feed,game=game,retry=self.clock()+(300 if final else 2))
        except Exception:
            with self.lock:entry['retry']=self.clock()+15
        finally:
            with self.lock:entry['pending']=False
            self.slots.release()

MLB_GEOMETRY=MLBGeometryCache()


class TrackerBusy(Exception):pass
class TrackerUnavailable(Exception):pass
class TrackerNotFound(Exception):pass  # Sept 29: ESPN has no such game (404, not a retryable outage)

def fetch_summary(league,event_id):
    route=LEAGUES[league][0]
    url='https://site.api.espn.com/apis/site/v2/sports/'+route+'/summary?event='+event_id
    # Same client header as server.get_json. ESPN's edge answers Access Denied (403) for
    # unrecognised agents such as 'Orbital sports metadata/1' while serving this one.
    request=urllib.request.Request(url,headers={'Accept':'application/json','User-Agent':'curl/8.7.1'})
    try:
        with urllib.request.urlopen(request,timeout=8) as response:
            data=response.read(MAX_BYTES+1)
    except urllib.error.HTTPError as error:
        if error.code in (400,404):raise TrackerNotFound('No such game') from None
        raise
    if len(data)>MAX_BYTES:raise TrackerUnavailable('Summary exceeds bounded size')
    result=json.loads(data)
    if not isinstance(result,dict):raise TrackerUnavailable('Summary unavailable')
    return MLB_GEOMETRY.enrich(result) if league=='MLB' else result

"""Pinned sanitized football-reference fragment compiled into tracker.py.

No imports or I/O. Uses the existing tracker's bounded field sanitizers.
"""


def football_reference_drives(raw):
    source = raw.get('drives')
    if not isinstance(source, dict):
        raise ValueError('Reference football drive object')
    previous, current = source.get('previous', []), source.get('current')
    if not isinstance(previous, list) or len(previous) > 128 or current is not None and not isinstance(current, dict):
        raise ValueError('Reference football drive bound')
    count = 0

    def clean_play(play):
        if not isinstance(play, dict):
            raise ValueError('Reference football play object')
        ident = identity(play.get('id'))
        if not ident:
            raise ValueError('Reference football play identity')
        row = {'id': ident}
        for key, limit in (('text', 400), ('wallclock', 40)):
            if key in play:
                row[key] = text(play[key], limit)
        for key, bounds in (('awayScore', (0, 999)), ('homeScore', (0, 999)),
                            ('statYardage', (-100, 110)), ('scoreValue', (0, 99))):
            if key in play:
                row[key] = number(play[key], *bounds)
        if type(play.get('scoringPlay')) is bool:
            row['scoringPlay'] = play['scoringPlay']
        for key, fields in (('period', ('number', 'type', 'displayValue')),
                            ('clock', ('displayValue',)), ('type', ('id', 'type', 'text'))):
            value = play.get(key)
            if isinstance(value, dict):
                row[key] = {k: (text(value[k], 80) if isinstance(value[k], str) else number(value[k]))
                            for k in fields if k in value}
        for key in ('start', 'end'):
            value = play.get(key)
            if isinstance(value, dict):
                item = {}
                for field, bounds in (('yardsToEndzone', (0, 100)), ('down', (1, 4)), ('distance', (0, 100))):
                    if field in value:
                        item[field] = number(value[field], *bounds)
                for field, limit in (('downDistanceText', 100), ('shortDownDistanceText', 100), ('possessionText', 30)):
                    if field in value:
                        item[field] = text(value[field], limit)
                # Preserve the strict ORIGINAL end verdict before sanitized
                # labels can lose contradictory evidence. False is a barrier,
                # never an inferred source/yardline Goal assertion.
                if key == 'end':
                    item['goalToGo'] = football_goal_to_go(value)
                elif type(value.get('goalToGo')) is bool:
                    item['goalToGo'] = value['goalToGo']
                if isinstance(value.get('team'), dict):
                    item['team'] = {'id': identity(value['team'].get('id'))}
                row[key] = item
        if isinstance(play.get('team'), dict):
            row['team'] = {'id': identity(play['team'].get('id'))}
        return row

    def clean_drive(drive):
        nonlocal count
        if not isinstance(drive, dict):
            raise ValueError('Reference football drive object')
        rows = drive.get('plays', [])
        if not isinstance(rows, list) or len(rows) > MAX_PLAYS or count + len(rows) > MAX_PLAYS:
            raise ValueError('Reference football play bound')
        count += len(rows)
        result = {'id': identity(drive.get('id')),
                  'team': {'id': identity((drive.get('team') or {}).get('id'))},
                  'plays': [clean_play(play) for play in rows]}
        for key, limit in (('displayResult', 80), ('result', 80), ('description', 160)):
            if key in drive:
                result[key] = text(drive[key], limit)
        if 'yards' in drive:
            result['yards'] = number(drive['yards'], -100, 1000)
        return result

    result = {'previous': [clean_drive(drive) for drive in previous]}
    if current is not None:
        result['current'] = clean_drive(current)
    return result


def reference_summary(raw,league=None):
    """Only the public fields OCR consumes; no upstream URLs or viewer identity."""
    def reference_team(competitor):
        source=competitor.get('team') or {}
        result={'id':identity(source.get('id')) or identity(competitor.get('id')),
                'abbreviation':text(source.get('abbreviation'),12)}
        if league in ('NFL','College football'):
            for field in ('displayName','shortDisplayName','location'):
                value=source.get(field)
                label=text(value,60) if isinstance(value,str) and len(value)<=60 and not any(ord(c)<32 or ord(c)==127 for c in value) else None
                if label is not None:result[field]=label
        return result
    allowed={'id','text','wallclock','summaryType','atBatId','atBatPitchNumber','pitchVelocity','outs','awayScore','homeScore'}
    nested={'period':('number','type','displayValue'),'resultCount':('balls','strikes'),
            'pitchType':('text',),'type':('type','text'),'clock':('displayValue',)}
    source=list(plays(raw))
    drives=raw.get('drives') or {}
    for drive in (drives.get('previous') or [])+([drives['current']] if isinstance(drives.get('current'),dict) else []):
        rows=drive.get('plays') or []
        if len(rows)>MAX_PLAYS or len(source)+len(rows)>MAX_PLAYS*2:raise ValueError('Reference play limit')
        source.extend(rows)
    rows={}
    for play in source:
        if not isinstance(play,dict) or not identity(play.get('id')):continue
        row={k:(text(v,400) if isinstance(v,str) else number(v)) for k,v in play.items() if k in allowed}
        for key,fields in nested.items():
            value=play.get(key)
            if isinstance(value,dict):row[key]={k:(text(value[k],80) if isinstance(value[k],str) else number(value[k])) for k in fields if k in value}
        rows[row['id']]=row
    header=raw.get('header') or {};comps=[]
    for comp in (header.get('competitions') or [])[:2]:
        comps.append({'id':identity(comp.get('id')),'date':text(comp.get('date'),40),
            'status':{'type':{'state':text(((comp.get('status') or {}).get('type') or {}).get('state'),12)}},
            'competitors':[{'team':reference_team(c),
                            'homeAway':text(c.get('homeAway'),8)} for c in (comp.get('competitors') or [])[:2]]})
    result={'header':{'id':identity(header.get('id')),'competitions':comps},'plays':list(rows.values())[-MAX_PLAYS:]}
    if 'drives' in raw:result['drives']=football_reference_drives(raw)
    if league in ('NBA','WNBA','NHL','MLS'):
        from generic_reference import extend
        result=extend(result,raw,league)
    if len(json.dumps(result,separators=(',',':')).encode())>MAX_BYTES:raise ValueError('Reference bounded size')
    return result


class ReferenceJournal:
    EVENT_BYTES=16*1024*1024
    TOTAL_BYTES=128*1024*1024
    FILES=64

    def __init__(self,directory,background=True):
        import queue
        self.directory=Path(directory)/'revisions'
        self.queue=queue.Queue(maxsize=2)
        self.status={'state':'IDLE','dropped':0,'written':0}
        self.cache={}
        self.lock=threading.Lock()
        if background:threading.Thread(target=self._run,daemon=True,name='reference-history').start()

    def submit(self,league,event,generation,received,monotonic,reference,timeline):
        # Existing sanitized snapshots only; no fetch, disk work or waiting here.
        import queue
        try:self.queue.put_nowait((league,event,generation,received,monotonic,copy.deepcopy(reference),copy.deepcopy(timeline)))
        except queue.Full:
            self.status={**self.status,'state':'DROPPED','dropped':self.status['dropped']+1}
        return dict(self.status)

    def _run(self):
        while True:
            item=self.queue.get()
            try:self.record(*item)
            except Exception:self.status={**self.status,'state':'UNAVAILABLE'}
            finally:self.queue.task_done()

    @staticmethod
    def _json(value):return json.dumps(value,sort_keys=True,separators=(',',':'),allow_nan=False).encode()

    def record(self,league,event,generation,received,monotonic,reference,timeline):
        import fcntl
        if league not in LEAGUES or not re.fullmatch(r'[0-9]{1,12}',event):raise ValueError('Journal identity')
        if not all(isinstance(v,(int,float)) and not isinstance(v,bool) and math.isfinite(v) for v in (received,monotonic)):
            raise ValueError('Journal clock')
        # Remove mutable cache timing fields. Raw provider timestamps remain strings.
        normalized={r['id']:{k:v for k,v in r.items() if k not in ('first_seen_at','changed_at','complete_first_seen_at')}
                    for r in timeline if identity(r.get('id'))}
        raw={r['id']:r for r in reference['plays']}
        current={key:{'reference':raw.get(key),'normalized':normalized.get(key)} for key in raw.keys()|normalized.keys()}
        current['_header']={'header':reference['header']}
        with self.lock:
            self.directory.mkdir(parents=True,exist_ok=True)
            if self.directory.is_symlink():raise OSError('Unsafe journal directory')
            fd=os.open(self.directory/'journal.lock',os.O_CREAT|os.O_RDWR|os.O_NOFOLLOW,0o600)
            try:
                fcntl.flock(fd,fcntl.LOCK_EX)
                path=self.directory/(league.replace(' ','_')+'-'+event+'.jsonl')
                files=list(self.directory.glob('*.jsonl'))
                if any(p.is_symlink() for p in files):raise OSError('Unsafe journal file')
                size=path.stat().st_size if path.exists() else 0
                if size>self.EVENT_BYTES:raise ValueError('Journal oversized')
                # Reload after external append/restart. Never truncate a partial record.
                cached=self.cache.get(path)
                if cached and cached[0]==size:previous,last,sequence=cached[1:]
                else:
                    previous={};last=None;sequence=0
                    if size:
                        with open(path,'rb') as stream:
                            for line in stream:
                                if not line.endswith(b'\n'):raise ValueError('Incomplete journal record')
                                record=json.loads(line);digest=record.pop('record_sha256')
                                if hashlib.sha256(self._json(record)).hexdigest()!=digest or record['previous']!=last or record['sequence']!=sequence+1:
                                    raise ValueError('Journal chain mismatch')
                                if record['event']!=event or record['league']!=league:raise ValueError('Journal scope')
                                previous.update(record['changes']);last=digest;sequence=record['sequence']
                changes={k:v for k,v in current.items() if previous.get(k)!=v}
                if not changes:return
                # Absence from a bounded provider window is not a deletion/correction.
                body={'schema':1,'league':league,'event':event,'publisher_generation':generation,
                      'sequence':sequence+1,'previous':last,'observed_at':received,'observed_monotonic_s':monotonic,
                      'observation_point':'fetcher_returned_before_normalization',
                      'provider_occurrence_time_calibrated':False,'changes':changes}
                digest=hashlib.sha256(self._json(body)).hexdigest()
                data=self._json({**body,'record_sha256':digest})+b'\n'
                total=sum(p.stat().st_size for p in files)
                if size+len(data)>self.EVENT_BYTES or total+len(data)>self.TOTAL_BYTES or (not path.exists() and len(files)>=self.FILES):
                    self.status={**self.status,'state':'FULL'};return
                out=os.open(path,os.O_WRONLY|os.O_APPEND|os.O_CREAT|os.O_NOFOLLOW,0o600)
                try:
                    view=memoryview(data)
                    while view:
                        count=os.write(out,view)
                        if count<=0:raise OSError('Incomplete journal write')
                        view=view[count:]
                    os.fsync(out)
                finally:os.close(out)
                previous.update(copy.deepcopy(changes))
                self.cache[path]=(size+len(data),previous,digest,sequence+1)
                # Bound worker memory separately; persistent files retain the evidence.
                while len(self.cache)>24:self.cache.pop(next(iter(self.cache)))
                self.status={**self.status,'state':'RECORDING','written':self.status['written']+1}
            finally:os.close(fd)



_public_football_source=b'"""Latest public football presentation from a matching source drive array.\n\nThis does not order, rewrite or release any viewer-picture timeline. Canonical\nstore rows, revisions, report clocks and reference files remain untouched.\n"""\nimport copy\n\n\ndef play_identity(play):\n    return {key: play.get(key) for key in\n            (\'id\', \'period\', \'clock\', \'awayScore\', \'homeScore\', \'text\', \'type\', \'start\', \'end\')}\n\n\ndef _ordered_snapshot(snapshot, reference, timing):\n    if not isinstance(snapshot, dict) or snapshot.get(\'league\') not in (\'NFL\', \'College football\'):\n        return None\n    if not isinstance(reference, dict) or not isinstance(timing, dict):\n        return None\n    observed = snapshot.get(\'source_observation\', {})\n    pairs = [(\'generation\', \'generation\'), (\'revision\', \'revision\'),\n             (\'received_at\', \'received_at\'), (\'observed_at\', \'observed_monotonic_s\')]\n    if any(observed.get(a) is None or observed.get(a) != timing.get(b) for a, b in pairs):\n        return None\n    header = reference.get(\'header\', {})\n    if str(header.get(\'id\', \'\')) != snapshot.get(\'game_id\'):\n        return None\n    drives = reference.get(\'drives\', {})\n    previous = drives.get(\'previous\', [])\n    current = drives.get(\'current\')\n    if not isinstance(previous, list) or len(previous) > 100:\n        return None\n    ordered = previous + ([current] if isinstance(current, dict) else [])\n    seen_drives, positions, source_plays = {}, {}, {}\n    for drive in ordered:\n        if not isinstance(drive, dict) or not drive.get(\'id\'):\n            return None\n        ident = str(drive[\'id\'])\n        plays = drive.get(\'plays\')\n        if not isinstance(plays, list) or len(plays) > 800 or any(not isinstance(p, dict) for p in plays):\n            return None\n        # ESPN repeats its current drive in previous at a period boundary.\n        if ident in seen_drives:\n            if [play_identity(p) for p in plays] != [play_identity(p) for p in seen_drives[ident]]:\n                return None\n            continue\n        seen_drives[ident] = plays\n        for play in plays:\n            if not isinstance(play, dict) or not play.get(\'id\'):\n                return None\n            pid = str(play[\'id\'])\n            if pid in positions:\n                return None\n            positions[pid] = len(positions)\n            source_plays[pid] = play\n    events = snapshot.get(\'events\', [])\n    if not events or len(events) > 4096:\n        return None\n    ids = [row.get(\'event_id\') for row in events]\n    if len(set(ids)) != len(ids) or any(pid not in positions for pid in ids):\n        return None\n    # Identity and observation agreement do not excuse inconsistent play facts.\n    for row in events:\n        source = source_plays[row[\'event_id\']]\n        state = row.get(\'state_after\', {})\n        if (source.get(\'period\', {}).get(\'number\') != state.get(\'period\') or\n            source.get(\'clock\', {}).get(\'displayValue\') != state.get(\'clock\') or\n            source.get(\'awayScore\') != state.get(\'away\') or\n            source.get(\'homeScore\') != state.get(\'home\')):\n            return None\n    result = copy.deepcopy(snapshot)\n    result[\'events\'].sort(key=lambda row: positions[row[\'event_id\']])\n    tail = result[\'events\'][-1]\n    latest = copy.deepcopy(tail[\'state_after\'])\n    latest.update(state=snapshot[\'latest\'][\'state\'], phase=tail.get(\'phase\', \'play\'))\n    # Keep explicit lifecycle authority, never infer a final from a play.\n    if tail[\'event_id\'] == events[-1][\'event_id\']:\n        for key in (\'status\', \'status_provenance\', \'start\'):\n            if key in snapshot[\'latest\']:\n                latest[key] = copy.deepcopy(snapshot[\'latest\'][key])\n    result[\'latest\'] = latest\n    result[\'public_order_proof\'] = {\'basis\': \'matching_source_drive_array\',\n        \'context_event_id\': tail[\'event_id\'], \'generation\': observed[\'generation\'],\n        \'revision\': observed[\'revision\']}\n    return result\n\n\ndef ordered_snapshot(snapshot, reference, timing):\n    try:\n        return _ordered_snapshot(snapshot, reference, timing)\n    except (TypeError, KeyError, AttributeError):\n        return None\n\n\ndef public_result(result, reference, timing, formatter):\n    canonical = result.get(\'game_snapshot\')\n    presentation = ordered_snapshot(canonical, reference, timing)\n    if presentation is None:\n        return result\n    shown = formatter.with_latest(result, presentation)\n    # with_latest may retain the raw model when state is unchanged; explicitly\n    # project summary fields from the same presentation used by its renderer.\n    shown = {**shown, **formatter.overlay_latest(shown, presentation)}\n    shown[\'game_snapshot\'] = copy.deepcopy(canonical)\n    shown[\'public_order_proof\'] = presentation[\'public_order_proof\']\n    return shown\n'
